// Format diagnosis result into farmer-friendly Hindi message
const data = $input.first().json;

const event = data.event || 'send_notification';
const phone = data.phone || '';
const channel = data.channel || 'sms';
const metadata = data.metadata || data;

// Extract diagnosis fields
const disease = metadata.disease_name || data.disease || 'Unknown';
const confidence = metadata.confidence || data.confidence || 0;
const treatment = metadata.treatment || data.treatment || '';
const pesticide = metadata.pesticide || data.pesticide || '';
const vendor = metadata.nearest_vendor || '';
const location = metadata.location || {};

// Confidence percentage
const confPercent = Math.round(confidence * 100);

// Build Hindi notification message
let message = '';

if (confPercent >= 65) {
  message = `🌾 *कृषि-सारथी अलर्ट* 🌾\n\n`;
  message += `आपकी फसल में *${disease}* detected हुआ है (${confPercent}% confidence).\n\n`;

  if (treatment) {
    message += `💊 *इलाज:*\n${treatment}\n\n`;
  }

  if (pesticide) {
    message += `🧴 *Recommended pesticide:* ${pesticide}\n\n`;
  }

  if (vendor) {
    message += `🏪 *Nearest shop:* ${vendor}\n\n`;
  }

  message += `📞 Kisan Helpline: 1800-180-1551 (toll free)\n`;
  message += `— कृषि-सारथी AI Assistant`;
} else {
  // Low confidence — softer message
  message = `🌾 *कृषि-सारथी* 🌾\n\n`;
  message += `आपकी फसल की जांच हो रही है. हमारे विशेषज्ञ जल्द संपर्क करेंगे.\n\n`;
  message += `📞 Kisan Helpline: 1800-180-1551\n`;
  message += `— कृषि-सारथी AI Assistant`;
}

const notification = {
  notification_id: data.notification_id || `NOTIF-${Date.now()}`,
  phone: phone,
  channel: channel,
  message: message,
  disease: disease,
  confidence: confPercent,
  treatment: treatment,
  pesticide: pesticide,
  formatted_at: new Date().toISOString(),
  language: 'hi',
};

return [{ json: notification }];

// Simulate SMS send (replace with Twilio/MSG91 in production)
const notification = $input.first().json;

const smsLog = {
  type: 'SMS',
  to: notification.phone,
  message_preview: notification.message.substring(0, 160),
  full_message: notification.message,
  sent_at: new Date().toISOString(),
  status: 'sent',
  provider: 'mock_sms',
  notification_id: notification.notification_id,
  note: 'Production: Replace this node with Twilio SMS or MSG91 node'
};

console.log('[Krishi-Sarthi SMS]', JSON.stringify({
  to: smsLog.to,
  preview: smsLog.message_preview,
  status: 'sent'
}));

return [{ json: { ...notification, delivery: smsLog } }];

